def run_contract_test_file() -> None:
    def _extra(parsed):
        if parsed.group_rm:
            os.environ[contract_env_name("GROUP_RM")] = "1"

    run_contract_test_for_file(
        __file__,
        path_args=[
            "eval-function-path",
            "custom-rm-path",
            "dynamic-sampling-filter-path",
            "buffer-filter-path",
            "data-source-path",
            "rollout-sample-filter-path",
            "rollout-all-samples-process-path",
